host_operator_src="""
#include "conv_pointwise_2d_custom_tiling.h"
#include "register/op_def_registry.h"

namespace optiling {
static constexpr uint32_t BLOCKS = 8;
static constexpr uint32_t DEFAULT_TILE_M = 64; // simple tiling along M
static constexpr uint32_t DEFAULT_TILE_N = 64; // simple tiling along N

static ge::graphStatus TilingFunc(gert::TilingContext* context)
{
    ConvPointwise2dCustomTilingData tiling;
    // x2d shape: [m, k]
    const gert::Shape* x_shape = context->GetInputShape(0);
    const gert::Shape* w_shape = context->GetInputShape(1); // weight_ktn shape: [k, n]

    if (x_shape == nullptr || w_shape == nullptr || x_shape->GetOriginShape().GetDimNum() != 2 || w_shape->GetOriginShape().GetDimNum() != 2) {
        return ge::GRAPH_FAILED;
    }

    uint64_t m = x_shape->GetOriginShape().GetDim(0);
    uint64_t k = x_shape->GetOriginShape().GetDim(1);
    uint64_t k_w = w_shape->GetOriginShape().GetDim(0);
    uint64_t n = w_shape->GetOriginShape().GetDim(1);
    if (k != k_w) {
        return ge::GRAPH_FAILED;
    }

    context->SetBlockDim(BLOCKS);
    tiling.set_m(static_cast<uint32_t>(m));
    tiling.set_k(static_cast<uint32_t>(k));
    tiling.set_n(static_cast<uint32_t>(n));
    tiling.set_tileM(DEFAULT_TILE_M);
    tiling.set_tileN(DEFAULT_TILE_N);

    tiling.SaveToBuffer(context->GetRawTilingData()->GetData(), context->GetRawTilingData()->GetCapacity());
    context->GetRawTilingData()->SetDataSize(tiling.GetDataSize());

    size_t* currentWorkspace = context->GetWorkspaceSizes(1);
    currentWorkspace[0] = 0;
    return ge::GRAPH_SUCCESS;
}
}

namespace ge {
static ge::graphStatus InferShape(gert::InferShapeContext* context)
{
    const gert::Shape* x_shape = context->GetInputShape(0); // [m, k]
    const gert::Shape* w_shape = context->GetInputShape(1); // [k, n]
    if (x_shape == nullptr || w_shape == nullptr || x_shape->GetOriginShape().GetDimNum() != 2 || w_shape->GetOriginShape().GetDimNum() != 2) {
        return GRAPH_FAILED;
    }
    gert::Shape* y_shape = context->GetOutputShape(0);
    uint64_t m = x_shape->GetOriginShape().GetDim(0);
    uint64_t n = w_shape->GetOriginShape().GetDim(1);
    gert::Shape out({static_cast<int64_t>(m), static_cast<int64_t>(n)});
    *y_shape = out;
    return GRAPH_SUCCESS;
}

static ge::graphStatus InferDataType(gert::InferDataTypeContext* context)
{
    // output is float32
    context->SetOutputDataType(0, ge::DT_FLOAT);
    return ge::GRAPH_SUCCESS;
}
}

